@model CreateQuestionViewModel
@{ ViewData["Title"] = "Create question"; }
<section class="auth-wrap"><div class="card auth-card"><h1>Add quiz question</h1><form asp-action="CreateQuestion" method="post" class="form">@Html.AntiForgeryToken()<label asp-for="QuizId">Quiz</label><select asp-for="QuizId" asp-items="Model.Quizzes"></select><span asp-validation-for="QuizId" class="field-error"></span><label asp-for="QuestionText"></label><textarea asp-for="QuestionText" rows="3"></textarea><span asp-validation-for="QuestionText" class="field-error"></span><label asp-for="OptionA">Option 1</label><input asp-for="OptionA" /><span asp-validation-for="OptionA" class="field-error"></span><label asp-for="OptionB">Option 2</label><input asp-for="OptionB" /><span asp-validation-for="OptionB" class="field-error"></span><label asp-for="OptionC">Option 3</label><input asp-for="OptionC" /><span asp-validation-for="OptionC" class="field-error"></span><label asp-for="OptionD">Option 4</label><input asp-for="OptionD" /><span asp-validation-for="OptionD" class="field-error"></span><label asp-for="CorrectOptionNumber">Correct option number</label><input asp-for="CorrectOptionNumber" type="number" min="1" max="4" /><span asp-validation-for="CorrectOptionNumber" class="field-error"></span><div class="row top-gap"><a asp-action="Index" class="btn ghost">Back</a><button type="submit" class="btn">Save question</button></div></form></div></section>
@section Scripts { <partial name="_ValidationScriptsPartial" /> }
